-- public.at_station(p_world uuid, p_uid uuid, p_station text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.at_station(p_world uuid, p_uid uuid, p_station text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  select case p_station
    when 'campfire' then
      exists (select 1 from placed_near(p_world, p_uid, 'campfire', null, 2.6) p where placed_lit(p))
      or exists (select 1 from placed_near(p_world, p_uid, 'furniture', null, 2.6) p
                 join furniture_def d on d.id = p.sub where d.hearth and placed_lit(p))
    -- An oven, alight: no other hearth (`Game.litOvenNear`).
    when 'oven' then
      exists (select 1 from placed_near(p_world, p_uid, 'furniture', 'oven', 2.6) p where placed_lit(p))
    when 'smelter' then
      exists (select 1 from placed_near(p_world, p_uid, 'smelter', null, 2.6) p where placed_lit(p))
    else
      exists (select 1 from placed_near(p_world, p_uid, 'furniture', p_station, 2.4))
    end
$function$
